TTI.setupPointMerge=function(){
 const button=el('button','⇄ Unește puncte','add-point');$('sidebar').insertBefore(button,$('sidebar').querySelector('.search'));let chosen=new Map(),halos=[],operationId=null;
 const clear=()=>{halos.forEach(h=>map.removeLayer(h));halos=[];};
 const cancel=()=>{this.mergePicking=false;chosen.clear();operationId=null;clear();button.textContent='⇄ Unește puncte';};this.cancelPointMerge=cancel;
 const draw=()=>{clear();for(const f of chosen.values())halos.push(L.circleMarker(f.coordinates,{radius:22,color:'#102735',weight:3,fillColor:'#32c7ad',fillOpacity:.2,interactive:false}).addTo(map));};
 this.toggleMergePoint=f=>{if(this.busy||f.type!=='Point'||f.deleted)return;if(chosen.has(f.id))chosen.delete(f.id);else{if(chosen.size===12){alert('Poți uni maximum 12 puncte odată.');return;}chosen.set(f.id,f);}operationId=null;draw();review();};
 this.beginPointMerge=f=>{if(this.busy)return;this.cancelCableSelection();this.cancelPointCreation?.();cancel();this.mergePicking=true;button.textContent='Anulează selecția punctelor';if(f)chosen.set(f.id,f);draw();review();};
 button.onclick=()=>{if(this.busy)return;if(this.mergePicking){cancel();$('details').hidden=true;}else this.beginPointMerge();};
 $('sidebar').addEventListener('click',event=>{const other=event.target.closest('.add-point');if(other&&other!==button&&this.mergePicking){cancel();$('details').hidden=true;}},true);
 $('close-details').addEventListener('click',cancel);
 function review(){
  const previous=document.querySelector('#merge-target')?.value,oldLayer=document.querySelector('#merge-layer')?.value;selected=null;$('details').hidden=false;const content=$('detail-content');content.replaceChildren(el('h2','Unește puncte','detail-title'));const box=el('section',undefined,'point-editor');box.append(el('p','Click pe punctele de pe hartă pentru a le selecta sau deselecta. Alege între 2 și 12 puncte.'),el('strong',chosen.size+' puncte selectate'));
  const pickerLabel=el('label','Adaugă un punct din listă (inclusiv puncte suprapuse)'),picker=el('select'),empty=el('option','Selectează un punct…');picker.setAttribute('aria-label','Adaugă un punct din listă');empty.value='';picker.append(empty);for(const f of TTI.all.filter(f=>f.type==='Point'&&!f.deleted&&!chosen.has(f.id))){const option=el('option',(f.name||'Fără nume')+' · '+short(f.category)+' · '+f.coordinates.map(n=>n.toFixed(6)).join(', '));option.value=f.id;picker.append(option);}pickerLabel.append(picker);const add=el('button','Adaugă la selecție');add.disabled=true;picker.onchange=()=>add.disabled=!picker.value;add.onclick=()=>{const f=TTI.all.find(f=>f.id===picker.value);if(f)TTI.toggleMergePoint(f);};box.append(pickerLabel,add);
  for(const f of chosen.values()){const row=el('article',undefined,'observation');row.append(el('strong',f.name||'Punct fără nume'),el('p',short(f.category)+' · '+f.photos.length+' fotografii · '+(f.observations?.length||0)+' observații'));const remove=el('button','Scoate din selecție');remove.onclick=()=>TTI.toggleMergePoint(f);row.append(remove);box.append(row);}
  const label=el('label','Punctul păstrat (nume și poziție)'),target=el('select');target.id='merge-target';target.setAttribute('aria-label','Punctul păstrat');for(const f of chosen.values()){const option=el('option',(f.name||'Fără nume')+' · '+f.coordinates.map(n=>n.toFixed(6)).join(', '));option.value=f.id;target.append(option);}if(chosen.has(previous))target.value=previous;label.append(target);box.append(label);
  const layerLabel=el('label','Stratul rezultat'),layer=el('select');layer.id='merge-layer';layer.setAttribute('aria-label','Stratul rezultat');for(const key of data.categories){const option=el('option',short(key));option.value=key;layer.append(option);}layer.value=(chosen.has(previous)?oldLayer:null)||chosen.get(target.value)?.category||'';target.onchange=()=>{layer.value=chosen.get(target.value)?.category||'';operationId=null;};layer.onchange=()=>operationId=null;layerLabel.append(layer);box.append(layerLabel,el('p','Fotografiile și observațiile sunt reunite în punctul păstrat. Celelalte puncte sunt ascunse. Poți anula unirea din istoricul comun dacă nu au apărut modificări ulterioare.'));
  const message=el('p',undefined,'save-status'),save=el('button','Unește punctele','save-point');save.disabled=chosen.size<2;save.onclick=async()=>{if(TTI.busy||chosen.size<2)return;const kept=chosen.get(target.value);if(!kept||!layer.value){message.textContent='Alege punctul păstrat și stratul.';return;}if(!confirm('Unești '+chosen.size+' puncte pentru toți utilizatorii? Se păstrează „'+kept.name+'” și poziția lui.'))return;operationId=operationId||crypto.randomUUID();const payload={id:operationId,target:kept.id,category:layer.value,points:[...chosen.values()].map(f=>({id:f.id,version:f.version}))};TTI.busy=true;box.querySelectorAll('button,select').forEach(n=>n.disabled=true);try{await TTI.request('/points/merge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});cancel();await TTI.refresh();const f=TTI.all.find(f=>f.id===kept.id);enabled.set(f.category,true);focus(f);}catch(e){message.textContent=e.message;const reload=el('button','Reîncarcă selecția');reload.onclick=async()=>{await TTI.refresh();chosen=new Map([...chosen].filter(([,f])=>!f.deleted));operationId=null;draw();review();};box.append(reload);}finally{TTI.busy=false;box.querySelectorAll('button,select').forEach(n=>n.disabled=false);}};
  box.append(save,message);content.append(box);$('details').scrollTop=0;
 }
};
